<?php require __DIR__.'/partials/header.php';$stream=$db->query('SELECT * FROM live_streams ORDER BY id DESC LIMIT 1')->fetch();$video='';if($stream && $stream['video_url']){ $u=parse_url($stream['video_url']);if(($u['host']??'')==='www.youtube.com' && isset($u['query'])){parse_str($u['query'],$v);if(preg_match('/^[A-Za-z0-9_-]{11}$/',$v['v']??''))$video=$v['v'];}elseif(($u['host']??'')==='youtu.be' && preg_match('/^[A-Za-z0-9_-]{11}$/',trim($u['path']??'','/')))$video=trim($u['path'],'/');} ?><section class="page-hero"><div class="wrap"><span class="eyebrow">GAME DAY</span><h1>LA <em>DIRETTA</em></h1><p>Segui la squadra attraverso i canali ufficiali quando è disponibile una trasmissione.</p></div></section><section class="wrap section"><div class="video-frame"><?php if($video && $stream['status']==='live'): ?><iframe src="https://www.youtube-nocookie.com/embed/<?= e($video) ?>" title="Diretta Bartoli Mechanics Basket" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy"></iframe><?php else: ?><div class="video-placeholder"><span class="play-icon">▶</span><h2>DIRETTA NON DISPONIBILE</h2><p>Al momento non è configurato uno streaming live verificato.</p><?php if($stream && $stream['video_url']): ?><a class="btn btn-ghost" href="<?= e($stream['video_url']) ?>" target="_blank" rel="noopener">Apri collegamento ↗</a><?php endif; ?></div><?php endif; ?></div><div class="result-row"><div><span class="eyebrow">INFORMAZIONI</span><h3><?= e($stream['title']??'Prossima diretta') ?></h3><p><?= e($stream['scheduled_at']??'Data da comunicare') ?></p></div><span class="live-pill"><?= e(strtoupper($stream['status']??'non disponibile')) ?></span></div><p class="fine-print">La pagina non simula una diretta: il player compare solo se è configurato un URL YouTube valido e lo stato è impostato su live.</p></section><?php require __DIR__.'/partials/footer.php'; ?>